-- Data contoh untuk dasbor lokal (60 pesanan, 45 hari terakhir, relatif terhadap tanggal impor).
-- Semua kode berawalan KS-DEMO- . Hapus kapan saja dengan:
--   DELETE FROM payment_logs WHERE order_code LIKE 'KS-DEMO-%';
--   DELETE FROM orders WHERE order_code LIKE 'KS-DEMO-%';   -- order_items ikut terhapus (ON DELETE CASCADE)
-- Impor setelah schema.sql dan seed.sql. Aman diimpor ulang (data lama KS-DEMO- dihapus dulu).
SET NAMES utf8mb4;
SET time_zone = '+07:00';
DELETE FROM payment_logs WHERE order_code LIKE 'KS-DEMO-%';
DELETE FROM orders WHERE order_code LIKE 'KS-DEMO-%';




























































